mapper.update:
update appointment_slot
slot_date = #{slotDate}, start_time = #{startTime}, end_time = #{endTime}, recurrence_type = #{recurrenceType}, recurrence_end_date = #{recurrenceEndDate}, max_people = #{maxPeople}, booked_count = #{bookedCount}, status = #{status}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select * from appointment_slot
where inheritor_id = #{inheritorId}
  and slot_date = #{slotDate}
  and status = 1

      and id != #{excludeId}

  and start_time < #{endTime}
  and end_time > #{startTime}
order by start_time
